-- Rev 2.3 review: a quantity on add-on lines, and one place for the supplements discount (docs/CHARGES_DESIGN.md).
-- Generated by `prisma migrate diff`, then the hand-written section below.

-- AlterTable
ALTER TABLE "RevenueEvent" ADD COLUMN     "quantity" INTEGER NOT NULL DEFAULT 1;

-- AlterTable
ALTER TABLE "OpenCharge" ADD COLUMN     "quantity" INTEGER NOT NULL DEFAULT 1;

-- CreateTable
CREATE TABLE "OpenChargeQuantity" (
    "id" BIGSERIAL NOT NULL,
    "openChargeId" TEXT NOT NULL,
    "quantity" INTEGER NOT NULL,
    "changedById" TEXT NOT NULL,
    "changedAt" TIMESTAMP(3) NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "OpenChargeQuantity_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "OpenChargeQuantity_openChargeId_idx" ON "OpenChargeQuantity"("openChargeId");

-- AddForeignKey
ALTER TABLE "OpenChargeQuantity" ADD CONSTRAINT "OpenChargeQuantity_openChargeId_fkey" FOREIGN KEY ("openChargeId") REFERENCES "OpenCharge"("id") ON DELETE RESTRICT ON UPDATE CASCADE;


-- =============================================================================
-- HAND-WRITTEN
-- =============================================================================

ALTER TABLE "OpenChargeQuantity" ENABLE ROW LEVEL SECURITY;
CREATE TRIGGER "OpenChargeQuantity_no_update_delete" BEFORE UPDATE OR DELETE ON "OpenChargeQuantity" FOR EACH ROW       EXECUTE FUNCTION nw_reject_ledger_mutation();
CREATE TRIGGER "OpenChargeQuantity_no_truncate"      BEFORE TRUNCATE         ON "OpenChargeQuantity" FOR EACH STATEMENT EXECUTE FUNCTION nw_reject_ledger_mutation();

-- A sensible bound on one line: 1 to 99 units.
ALTER TABLE "OpenCharge"         ADD CONSTRAINT "OpenCharge_quantity"         CHECK ("quantity" BETWEEN 1 AND 99);
ALTER TABLE "OpenChargeQuantity" ADD CONSTRAINT "OpenChargeQuantity_quantity" CHECK ("quantity" BETWEEN 1 AND 99);

-- A quantity changes only while the line is open: not after it was removed, nor after it was checked out.
CREATE OR REPLACE FUNCTION nw_open_charge_quantity_guard() RETURNS trigger AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM "OpenChargeRemoval" WHERE "openChargeId" = NEW."openChargeId")
     OR EXISTS (SELECT 1 FROM "RevenueEvent" WHERE "openChargeId" = NEW."openChargeId") THEN
    RAISE EXCEPTION 'open charge % is no longer open: its quantity cannot change', NEW."openChargeId" USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER "OpenChargeQuantity_open_only" BEFORE INSERT ON "OpenChargeQuantity" FOR EACH ROW EXECUTE FUNCTION nw_open_charge_quantity_guard();

-- The money rule, restated once more: a quantity of 1 to 99, and more than one only on an add-on line (a visit is one visit).
ALTER TABLE "RevenueEvent" DROP CONSTRAINT "RevenueEvent_consistent";
ALTER TABLE "RevenueEvent" ADD CONSTRAINT "RevenueEvent_consistent" CHECK (
  "creditsRedeemed" >= 0 AND "netPriceCents" >= 0 AND "discountCents" >= 0 AND "promotionCents" >= 0
  AND "discountPercent" BETWEEN 0 AND 100
  AND ("listPriceCents" IS NULL OR "listPriceCents" >= 0)
  AND (("promotionCents" > 0) = ("promotionId" IS NOT NULL))
  AND ("promotionCents" = 0 OR "discountCents" = 0)
  AND (("adjustmentCents" <> 0) = ("adjustmentReason" IS NOT NULL))
  AND ("adjustmentReason" IS DISTINCT FROM 'OTHER' OR length(btrim(coalesce("adjustmentNote", ''))) > 0)
  AND "taxRateMilli" BETWEEN 0 AND 100000
  AND ("taxRateMilli" = 0 OR "productId" IS NOT NULL)
  AND "taxCents" = (("netPriceCents"::bigint * "taxRateMilli" + 50000) / 100000)
  AND "quantity" BETWEEN 1 AND 99
  AND ("quantity" = 1 OR "openChargeId" IS NOT NULL)
  AND (("paymentType" = 'CASH'   AND "memberBenefit" IS NULL AND "creditsRedeemed" = 0 AND "listPriceCents" IS NOT NULL
        AND "netPriceCents" = "listPriceCents" - "discountCents" - "promotionCents" - "adjustmentCents"
        AND ("discountPercent" > 0 OR "discountCents" = 0))
    OR ("paymentType" = 'MEMBER' AND "memberBenefit" IS NOT NULL AND "netPriceCents" = 0
        AND "discountPercent" = 0 AND "discountCents" = 0 AND "promotionCents" = 0 AND "adjustmentCents" = 0
        AND ("memberBenefit" = 'CREDITS') = ("creditsRedeemed" > 0))
    OR ("paymentType" = 'DUES' AND "memberBenefit" IS NULL AND "creditsRedeemed" = 0
        AND "discountPercent" = 0 AND "discountCents" = 0 AND "promotionCents" = 0 AND "adjustmentCents" = 0
        AND "listPriceCents" IS NOT NULL AND "listPriceCents" > 0 AND "netPriceCents" = "listPriceCents"))
);

-- The open-line guard, restated: the charge carries the line's snapshots AND its quantity as it stood — the newest quantity change,
-- else the line's own — with list price = unit price × quantity.
CREATE OR REPLACE FUNCTION nw_open_charge_guard() RETURNS trigger AS $$
DECLARE
  oc record; oc_id text; qty integer;
BEGIN
  oc_id := NEW."openChargeId";   -- both tables name the line by this column
  IF oc_id IS NULL THEN RETURN NULL; END IF;
  IF EXISTS (SELECT 1 FROM "OpenChargeRemoval" WHERE "openChargeId" = oc_id) AND EXISTS (SELECT 1 FROM "RevenueEvent" WHERE "openChargeId" = oc_id) THEN
    RAISE EXCEPTION 'open charge % was both removed and checked out', oc_id USING ERRCODE = 'check_violation';
  END IF;
  IF TG_TABLE_NAME = 'RevenueEvent' THEN
    SELECT * INTO oc FROM "OpenCharge" WHERE "id" = oc_id;
    SELECT COALESCE((SELECT q."quantity" FROM "OpenChargeQuantity" q WHERE q."openChargeId" = oc_id ORDER BY q."id" DESC LIMIT 1), oc."quantity") INTO qty;
    IF oc."patientId" IS DISTINCT FROM NEW."patientId" OR oc."serviceId" IS DISTINCT FROM NEW."serviceId" OR oc."productId" IS DISTINCT FROM NEW."productId"
       OR oc."name" IS DISTINCT FROM NEW."serviceName" OR NEW."quantity" IS DISTINCT FROM qty
       OR NEW."listPriceCents" IS DISTINCT FROM oc."unitPriceCents" * qty
       OR oc."taxRateMilli" IS DISTINCT FROM NEW."taxRateMilli" THEN
      RAISE EXCEPTION 'charge % does not match the open line it was checked out from', NEW."id" USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NULL;
END;
$$ LANGUAGE plpgsql;

-- One place for the supplements discount (owner's decision at review): the "Supplements" service category now reads the member
-- discount on products (PlanProductDiscount), so its own per-tier rows are retired. Nothing else changes: the category, and the
-- Supplementation service in it, stay as they are.
DELETE FROM "PlanCategoryDiscount" WHERE "categoryId" IN (SELECT "id" FROM "DiscountCategory" WHERE "code" = 'SUPPLEMENTS');
